css:
.quantum-radio {
  position: relative;
  display: flex;
  align-items: center;
  margin-bottom: 20px;
  cursor: pointer;
}
.radio-label {
  color: aqua;
}

.quantum-radio input {
  position: absolute;
  opacity: 0;
  cursor: pointer;
}

.quantum-radio .radio-control {
  position: relative;
  width: 24px;
  height: 24px;
  border: 2px solid #4a4a8a;
  border-radius: 50%;
  margin-right: 15px;
  transition: all 0.3s ease;
  overflow: hidden;
}

.quantum-radio .radio-control::before {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: 0;
  height: 0;
  background: conic-gradient(
    from 90deg,
    #00ffcc,
    #00b3ff,
    #0066ff,
    #00b3ff,
    #00ffcc
  );
  border-radius: 50%;
  transform: translate(-50%, -50%) rotate(0deg);
  transition: all 0.4s ease;
  opacity: 0;
}

.quantum-radio:hover .radio-control {
  border-color: #00ffcc;
}

.quantum-radio input:checked ~ .radio-control {
  border-color: #00ffcc;
}

.quantum-radio input:checked ~ .radio-control::before {
  width: 24px;
  height: 24px;
  opacity: 1;
  animation: quantum-spin 2s linear infinite;
}

.quantum-radio input:checked ~ .radio-control::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: 8px;
  height: 8px;
  background: #00ffcc;
  border-radius: 50%;
  transform: translate(-50%, -50%);
  box-shadow: 0 0 5px #00ffcc;
}

@keyframes quantum-spin {
  0% {
    transform: translate(-50%, -50%) rotate(0deg);
  }
  100% {
    transform: translate(-50%, -50%) rotate(360deg);
  }
}
